/* questions owners ask, answered from the register: [question, answer, register ids]. Plain copy for pages and guides. */
const LAWFAQ = [
  ['Does a roofer in California need a license?', 'Yes for any job with a total price of $1,000 or more, and at any price if the work needs a permit or the roofer has employees. Roofing is the C-39 class of the Contractors State License Board. The license number must be on every ad, bid and contract.', ['c39', 'licnum']],
  ['How much can a roofer ask for as a down payment?', 'No more than $1,000 or 10 percent of the contract price, whichever is less. After that a contractor may not collect more than the value of the work done or the materials delivered.', ['downpay']],
  ['Can I cancel a roofing contract after I sign?', 'Yes. You have three business days from receiving your signed copy, five if you are a senior citizen, and seven if the contract repairs damage from a declared disaster. You may cancel by email, and anything you paid comes back within 10 days. The notice is not required if the contract was negotiated at the contractor\'s place of business.', ['cancel', 'emailcancel']],
  ['Can a roofer pay or waive my insurance deductible?', 'No. A contractor may not offer or give a discount meant to offset your deductible, unless your insurer has already set the claim amount and the work follows it.', ['deductible']],
  ['Can my roofer deal with the insurance company for me?', 'A roofer can inspect the roof, document the damage and write the estimate. Negotiating or settling a claim for pay takes a public adjuster license.', ['padj']],
  ['How long does an insurer have to answer a roof claim?', 'It must acknowledge the claim within 15 days, accept or deny it within 40 days of proof of claim, and pay within 30 days of accepting it.', ['claimclock']],
  ['Do I need a Class A roof?', 'In a Fire Hazard Severity Zone or other wildland urban interface area, replacing 50 percent or more of the roof within 12 months means the roof must meet the rules for a new roof, which call for a Class A assembly. Class A is the rating of the whole assembly, not of a shingle or a tile alone.', ['classa', 'fhsz']],
  ['Will a new roof lower my insurance?', 'Insurers that price on wildfire risk must take a Class A fire rated roof into account, but the rule sets no percentage and each insurer files its own. Ask your insurer for the figure before you decide.', ['sfw', 'fairplan']],
  ['What is a cool roof rule?', 'When more than half of a roof is replaced, the Energy Code requires reflective roofing in many California climate zones. The values depend on the building, the slope and the zone. Heavy roofs such as most tile, and several insulated attics, are exempt.', ['coolroof', 'coolex']],
  ['Do I need a permit to replace my roof?', 'It depends on the city or county. Los Angeles and San Francisco issue reroof permits; the City of San Diego requires none to renew a roof covering where the structure is not altered. Ask your building department.', ['permit']],
  ['Can I keep my wood shake roof?', 'Wood roofing may be sold or installed in California only if the State Fire Marshal has listed it, and some cities allow none. The City of Los Angeles prohibits all wood shake and shingle roofing, and wood shakes are not Class A.', ['shake']],
  ['My tile roof leaks but the tile looks fine. Why?', 'The underlayment under the tile wears out before the tile does. A lift and relay replaces the underlayment and flashings and puts sound tile back; cracked or broken tile may not be relaid.', ['reroof']],
  ['What happens to my solar panels when I reroof?', 'They come off and go back on. In Los Angeles County and the City of San Diego that takes its own permit, and an electrical or solar licensed contractor reinstalls them.', ['solarreroof']],
  ['Can a roofer raise prices after a wildfire or a storm?', 'For 180 days after an emergency is declared, a contractor may not charge more than 10 percent above its price from before the declaration for repairs, unless it can prove its own costs rose.', ['gouge']],
];
/* fill {City} {County} {Company} {Lic} {Office} {Phone} tokens, then house clean */
function fillCopy(s, ctx) {
  ctx = ctx || {}; const B = BRAND;
  const co = brandSet() ? (B.short || B.name) : 'Your company'; const map = { City: ctx.city || BRAND.city || 'California', County: ctx.county || '', Company: co, Firm: co, Lic: B.lic ? 'CSLB Lic. #' + B.lic : 'CSLB license number', Office: B.city || 'California', Phone: B.phone ? phoneFmt(B.phone) : '', Contact: B.contact || '' };
  return houseClean(String(s || '').replace(/\{(\w+)\}/g, (m, k) => map[k] != null ? map[k] : m));
}
